// Words splits text on whitespace.
func Words(s string) []string {
	return strings.Fields(s)
}

// Wrap wraps text into lines of at most `width` characters, breaking only at spaces.
// A word longer than width goes on a line of its own.
// Runs of whitespace collapse; no line begins or ends with a space.
// Empty or whitespace-only input returns an empty slice.
// A width of zero or less returns nil.
func Wrap(text string, width int) []string {
	if width <= 0 {
		return nil
	}

	fields := strings.Fields(text)
	if len(fields) == 0 {
		return nil
	}

	lines := []string{fields[0]}
	for i := 1; i < len(fields); i++ {
		word := fields[i]
		// If the word alone exceeds width, it gets its own line
		if len(word) > width {
			lines = append(lines, word)
			continue
		}
		// Try to fit on the current line
		candidate := lines[len(lines)-1] + " " + word
		if len(candidate) <= width {
			lines[len(lines)-1] = candidate
		} else {
			lines = append(lines, word)
		}
	}

	return lines
}

