package text

import "testing"

func TestWords(t *testing.T) {
	if len(Words("a b  c")) != 3 {
		t.Fatal("expected three words")
	}
}

func TestWrap(t *testing.T) {
	tests := []struct {
		name   string
		text   string
		width  int
		want   []string
	}{
		{
			name:  "nil for zero width",
			text:  "hello world",
			width: 0,
			want:  nil,
		},
		{
			name:  "nil for negative width",
			text:  "hello world",
			width: -5,
			want:  nil,
		},
		{
			name:  "empty string",
			text:  "",
			width: 10,
			want:    nil,
		},
		{
			name:  "whitespace only",
			text:  "   ",
			width: 10,
			want:    nil,
		},
		{
			name:  "single word shorter than width",
			text:  "hello",
			width: 10,
			want:    []string{"hello"},
		},
		{
			name:  "single word longer than width",
			text:  "supercalifragilistic",
			width: 5,
			want:  []string{"supercalifragilistic"},
		},
		{
			name:  "multiple words fit on one line",
			text:  "hello world foo",
			width: 20,
			want:  []string{"hello world foo"},
		},
		{
			name:  "words wrap at spaces",
			text:  "hello world foo bar",
			width: 10,
			want:  []string{"hello", "world foo", "bar"},
		},
		{
			name:  "collapses extra whitespace",
			text:  "hello    world\t\tsun",
			width: 10,
			want:  []string{"hello", "world sun"},
		},
		{
			name:  "no trailing or leading spaces",
			text: "  hello world  ",
			width: 10,
			want:  []string{"hello", "world"},
		},
		{
			name:  "long word gets own line",
			text:  "hi supercalifragilisticbye there",
			width: 8,
			want:  []string{"hi", "supercalifragilisticbye", "there"},
		},
		{
			name:  "exact fit",
			text:  "hello world",
			width: 11,
			want:    []string{"hello world"},
		},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			got := Wrap(tt.text, tt.width)
			if !equal(got, tt.want) {
				t.Errorf("Wrap(%q, %d) = %v, want %v", tt.text, tt.width, got, tt.want)
			}
		})
	}
}

func equal(a, b []string) bool {
	if a == nil && b == nil {
		return true
	}
	if (a == nil) != (b == nil) {
		return false
	}
	if len(a) != len(b) {
		return false
	}
	for i := range a {
		if a[i] != b[i] {
			return false
		}
	}
	return true
}
